        assert!(yaml.contains("Success"));
    }

    #[test]
    fn save_uses_atomic_write() {
        let temp = TempDir::new().unwrap();
        let project = ProjectId::from_path(temp.path()).unwrap();

        let mut state = StateStore::new(&project);
        state.update_step(
            "test_step",
